    # --- SPD-16: a user stop PARKS the journey, never cancels it ------------
    # Live run bf237280: Stop marked the workflow CANCELLED (terminal), so
    # the Resume the stop notification itself offers would have silently
    # started a NEW journey with a fresh worktree and re-paid every stage.
    # A stop is a pause; BLOCKED (owner human, in RESUMABLE) is its state.
    class _StopMc:
        def __init__(self):
            self.blocked = []
            self.cancelled = []

        def block(self, reason, evidence=None):
            self.blocked.append(reason)

        def cancel(self, reason):
            self.cancelled.append(reason)

    class _RaisingMc(_StopMc):
        def block(self, reason, evidence=None):
            raise ValueError("terminal")
    try:
        _smc = _StopMc()
        _park_stopped_run(_smc)
        ok.append(("SPD-16: a user stop parks the workflow BLOCKED "
                   "(resumable), never CANCELLED",
                   len(_smc.blocked) == 1 and not _smc.cancelled))
        ok.append(("SPD-16: the park reason says resume continues the journey",
                   "resume" in _smc.blocked[0].lower()))
        _park_stopped_run(None)   # no mc = workflow feature off; no raise
        _park_stopped_run(_RaisingMc())   # dying process: never raises
        ok.append(("SPD-16: parking is best-effort - no mc and a raising mc "
                   "are both survived", True))
    except NameError:
        ok.append(("SPD-16: a user stop parks the workflow BLOCKED "
                   "(resumable), never CANCELLED", False))
    except Exception as _e_smc:
        ok.append(("SPD-16: parking is best-effort - no mc and a raising mc "
                   "are both survived ({})".format(_e_smc), False))

