    #     gate row, and the stage still reads "done". Wiring a gate must
    #     never turn a stage that actually ran into "never reached".
    #   - HALTED: the row is there, so the plan line reports the gate's
    #     own outcome and reason instead of a bare "done".
    ok.append(("Task 6: a default run (plan_approval off) still reports the "
               "plan stage as done, never as never-reached",
               any(l.strip().startswith("[3/9] plan")
                   and "done" in l for l in _plog)))
    import tempfile as _t6tmp
    _t6db = Path(_t6tmp.mkdtemp()) / "t6.db"
    ledger.init(_t6db)
    _t6rid = ledger.start_run("T6-PA", project="p", db=_t6db)
    ledger.gate(_t6rid, "T6-PA", "comprehension", "pass", db=_t6db)
    ledger.gate(_t6rid, "T6-PA", "plan_approval", "unknown",
                unknown_reason="awaiting human approval", db=_t6db)
    ledger.end_run(_t6rid, "escalated", db=_t6db)
    _t6log = []
    _channel_summary(_t6rid, _t6db, _t6log.append)
    ok.append(("Task 6: a plan_approval halt reports the gate on the plan "
               "line of the RUN SUMMARY, with its reason",
               any(l.strip().startswith("[3/9] plan")
                   and "UNKNOWN" in l and "awaiting human approval" in l
                   for l in _t6log)))
