    with ledger.connect(e1_db) as con:
        _ids = {r["event_id"] for r in con.execute(
            "SELECT event_id FROM events WHERE run_id=?", (e1["run_id"],))}
    ok.append(("EVENTS: persist-before-emit - every seq exists in the ledger",
               all(s in _ids for s in _seqs)))

    # EVENTS: the terminal event - fires exactly once, last in the stream,
