    # QA then bought 24 production-repair calls for an impossible oracle.
    _oracle_proj = e1_td / "oracle-proj"
    _oracle_acc = e1_td / "oracle-acceptance"
    _oracle_proj.mkdir(); _oracle_acc.mkdir()
    (_oracle_proj / "api.py").write_text(
        "from dataclasses import dataclass\n\n"
        "@dataclass\nclass Counts:\n    good: int = 0\n\n"
        "@dataclass\nclass Report:\n    counts: Counts\n    ok: bool = False\n",
        encoding="utf-8")
    (_oracle_acc / "test_report.py").write_text(
        "def test_report(payload):\n"
        "    assert payload['counts']['ok'] is True\n",
        encoding="utf-8")
    _oracle_static = frozen_oracle_defects(
        {"results": {"raw_tail": "KeyError: 'ok'"}},
        _oracle_acc, _oracle_proj)
    ok.append(("FROZEN ORACLE: a nested serialized-member contradiction is "
               "proved statically and routed as a harness defect before "
               "any production repair is purchased",
               len(_oracle_static) == 1
               and "Counts has no member 'ok'" in _oracle_static[0]))

    # e4e: a HARNESS-DEFECT qa failure (invalid frozen-test contract) must
