    def _mk_e22_qa(proj):
        def _r(cmd, cwd, timeout=None):
            try:
                txt = (Path(cwd) / "src" / "calc.py").read_text()
            except OSError:
                txt = ""
            fails = ["test/acceptance/test_rt.py::t_fix{}".format(i)
                     for i in (1, 2, 3)
                     if "# FIX{}".format(i) not in txt]
            if not fails:
                return _P("16 passed in 0.1s", 0)
            lines = "\n".join("FAILED {} - AssertionError".format(f)
                              for f in fails)
            return _P("{}\n{} failed, {} passed in 0.1s".format(
                lines, len(fails), 16 - len(fails)), 1)
        return _r

    def _e22_fix(n, old, ):
        return json.dumps({"actions": [
            {"action": "replace", "path": "src/calc.py",
             "old": old, "new": old + "\n# FIX{}".format(n)}]})
