    ok.append(("H-2: no review/security/qa carry without the "
               "implementation",
               any("NOT carrying review/security/qa passes" in l
                   for l in e6i_tx.progress_log)
               and not any("blind review carried" in l
                           for l in e6i_tx.progress_log)
               and not any("security carried" in l
                           for l in e6i_tx.progress_log)))

    # BUDGET BRAKE: governor.max_tokens_per_run halts BEFORE the next
    # expensive stage - cleanly, never mid-task. Gates downstream stay
    # never-reached and a later resume continues from what passed, so a
    # small per-ticket budget degrades to "pause and continue", not waste.
    e8_proj = e1_td / "e2eproj8"
    (e8_proj / "src").mkdir(parents=True)
    (e8_proj / "pyproject.toml").write_text("", encoding="utf-8")
    (e8_proj / ".git").mkdir()
    (e8_proj / "src" / "calc.py").write_text("def add(a, b):\n    return a + b\n")
    # Mission Task 4 (2026-08-05): the cap is now checked before EVERY
    # model call by the metered authority, not only before develop /
    # review / qa / mutation. Calls 1 and 2 (cartographer, spec) run,
    # call 3 (the lead) is refused. So comprehension COMPLETES and every
    # stage from blast_radius onward is never reached - the same
    # never-reached honesty the old fixture proved, with a typed stop.
    #
    # [42/item7]/[43/H-P2] The stop is PREDICTIVE - a call is refused
    # when its fresh prompt plus its actor's ENFORCED response ceiling
    # cannot fit in what remains - so the cap below is DERIVED from a
    # measured twin rather than hardcoded: the largest cap that still
    # refuses call 3 (the lead). That keeps the original stop point (2
    # calls, halted at blast_radius) pinned while the projection, not
    # the breach, is what stops it.
    class _FixedTokTx(MockTransport):
        def chat(self, role, system, user):
            r = dict(super().chat(role, system, user))
            r["tokens_in"], r["tokens_out"] = 1000, 0
            return r

    _e8_replies = [
        json.dumps({"thought": "simple repo", "action": "done",
                    "patterns": E1_PATTERNS}),
        json.dumps(E1_SPEC),
        json.dumps({"thought": "one file", "action": "done",
                    "radius": E1_RADIUS}),
        json.dumps({"thought": "one step", "action": "done",
                    "plan": E1_PLAN}),
        json.dumps(E1_TESTSPEC),
    ]
    # [43/H-P2] The projection now reserves the ENFORCED ceiling (8,000
    # for the lead), so a hardcoded cap cannot pin "two calls run, the
    # third is refused" - the stop point depends on the real prompt
    # floors, which move with the agents' .md files. The cap is DERIVED:
    # a throwaway uncapped twin measures the first three calls' floors,
    # and the cap is set to the largest value that still refuses call 3
    # (spent-after-2 + floor-3 + ceiling - 1). Call 1 and call 2 fit at
    # that cap by construction (their floors are bounded by the spends
    # the formula already contains).
    import model_authority as _ma_e8
    _e8m_tx = _FixedTokTx(list(_e8_replies))
    _e8m_db = Path(tempfile.mkdtemp()) / "e8m.db"
    ledger.init(_e8m_db)
    _dev_mod._run, _qa_mod._run, _mut_mod._run = _green, _green, _mut
    try:
        run_ticket(_e8m_tx,
                   {"gates": {"comprehension": {"threshold": 1.0}},
                    "_workbench": str(e1_wb),
                    "_project_path": str(e8_proj)},
                   "E2E-8M", "add subtraction to calc",
                   _e8m_db, project="e2eproj8m")
    finally:
        _dev_mod._run, _qa_mod._run, _mut_mod._run = _saved
    _e8_floor = [(len(c["system"] or "") + len(c["user"] or "")) // 4
                 for c in _e8m_tx.calls[:3]]
    _e8_used = [max(1000, _e8_floor[i] + len(_e8_replies[i]) // 4)
                for i in range(2)]
    # Margin 500: the twin's prompts differ from e8's by a few chars
    # (project name), and the refusal must not hinge on a one-token
    # edge. Call 2 still fits (used2 + floor3 >> 500 by construction).
    _e8_cap = (sum(_e8_used) + _e8_floor[2]
               + _ma_e8.response_ceiling("lead") - 500)

    e8_tx = _FixedTokTx(list(_e8_replies))
    e8_cfg = {"gates": {"comprehension": {"threshold": 1.0}},
              "governor": {"max_tokens_per_run": _e8_cap},
              "_workbench": str(e1_wb), "_project_path": str(e8_proj)}
    _dev_mod._run, _qa_mod._run, _mut_mod._run = _green, _green, _mut
    try:
        e8 = run_ticket(e8_tx, e8_cfg, "E2E-8", "add subtraction to calc",
                        e1_db, project="e2eproj8")
    finally:
        _dev_mod._run, _qa_mod._run, _mut_mod._run = _saved
    with ledger.connect(e1_db) as con:
        e8_gates = {r["gate_name"]: r["outcome"] for r in con.execute(
            "SELECT gate_name, outcome FROM gates WHERE run_id=?",
            (e8["run_id"],))}
        e8_row = con.execute("SELECT outcome, failure_class FROM runs "
                             "WHERE run_id=?", (e8["run_id"],)).fetchone()
    ok.append(("BUDGET: no NEW model call begins once the cap is reached",
               len(e8_tx.calls) == 2 and len(e8_tx.replies) == 3))
    ok.append(("BUDGET: the stop is TYPED, with cap, source and stop point",
               e8["outcome"] == "budget_stop" and e8["cap"] == _e8_cap
               and e8["cap_source"] == "config"
               and e8["model_calls"] == 2
               and e8["halted_at"] == "blast_radius"))
    ok.append(("BUDGET: the run closes as escalated/budget_exceeded, never "
               "left running",
               e8_row["outcome"] == "escalated"
               and e8_row["failure_class"] == "budget_exceeded"))
    ok.append(("BUDGET: the stop is announced with the numbers",
               any("BUDGET STOP" in l for l in e8_tx.progress_log)))
    ok.append(("BUDGET: resume is NOT recommended automatically",
               any("Nothing is resumed automatically" in l
                   for l in e8_tx.progress_log)))
    # ---- CH-21: reached-but-incomplete is not never-reached --------------
    # The cap bit INSIDE blast_radius (halted_at above says so, and the
    # stage's own stage.started event is in the ledger). The stop sweep
    # starts at the cut stage, so before this fix the channel printed
    # "blast_radius not reached" for the very stage that was executing -
    # the operator's log denied the stage whose spend caused the stop.
    _ch21 = [l for l in e8_tx.progress_log if "blast_radius" in l
             and ("not reached" in l or "not completed" in l)]
    ok.append(("CH-21: the stage the run was stopped INSIDE reads "
               "'reached, not completed' - never 'not reached'",
               any("blast_radius reached, not completed" in l
                   for l in _ch21)
               and not any("blast_radius not reached" in l
                           for l in _ch21)))
    ok.append(("CH-21: and the stages downstream of it, which really were "
               "never entered, still read 'not reached' - the two facts "
               "stay distinguishable",
               any("mutation not reached" in l for l in e8_tx.progress_log)
               and not any("mutation reached, not completed" in l
                           for l in e8_tx.progress_log)))
    ok.append(("CH-21: a stage that already printed its own 'done in' line "
               "is not contradicted by the sweep",
               any("comprehension done in" in l
                   for l in e8_tx.progress_log)
               and not any("comprehension not reached" in l
                           or "comprehension reached, not completed" in l
                           for l in e8_tx.progress_log)))
    ok.append(("BUDGET: work that PASSED before the cap is still recorded",
               e8_gates.get("comprehension") == "pass"
               and "unit_tests" not in e8_gates))
    ok.append(("BUDGET: the effective cap and its source are printed at "
               "startup, before the first call",
               any("effective recorded-token cap: {} (source: config)"
                   .format(_e8_cap) in l
                   for l in e8_tx.progress_log)))
    # [42/item7] END TO END: the stop that fires in a real run_ticket is
    # the PREDICTIVE one, and the escalation payload the ledger records
    # carries what the refused call would have needed against what was
    # left. Without these numbers the operator cannot size the next run,
    # which is the whole point of refusing before the money is spent.
    with ledger.connect(e1_db) as con:
        _e8_esc = con.execute(
            "SELECT payload_json FROM events WHERE run_id=? AND "
            "event_type='escalation' ORDER BY event_id DESC LIMIT 1",
            (e8["run_id"],)).fetchone()
    _e8_pay = json.loads(_e8_esc["payload_json"]) if _e8_esc else {}
    ok.append(("[42/item7] the recorded budget stop is PREDICTIVE and "
               "says what it needed against what remained",
               _e8_pay.get("failure_class") == "budget_exceeded"
               and isinstance(_e8_pay.get("projected"), int)
               and isinstance(_e8_pay.get("headroom"), int)
               and _e8_pay["projected"] > _e8_pay["headroom"]
               and _e8_pay["tokens_spent"] <= 7000))
    ok.append(("[42/item7] the run stopped UNDER its cap - the 12,592 "
               "overshoot shape cannot recur",
               e8["tokens_spent"] <= 7000
               if "tokens_spent" in e8 else
               _e8_pay["tokens_spent"] <= 7000))
    # [42/item8] THE TERMINAL EVENT MUST NOT SAY "running". The live run
    # recorded {"state": "running", "at": "developer"} as its LAST event
    # while the runs row said escalated/budget_exceeded and the workflow
    # was BLOCKED. `terminal` was already derived correctly from
    # run_outcome; only the recorded state field still carried the raw
    # gate-derived reading, so every surface reading that field showed a
    # run that had stopped hours ago as still in flight.
    with ledger.connect(e1_db) as con:
        _e8_term = con.execute(
            "SELECT payload_json FROM events WHERE run_id=? AND "
            "payload_json LIKE '%run terminal%' ORDER BY event_id DESC "
            "LIMIT 1", (e8["run_id"],)).fetchone()
    _e8_tp = json.loads(_e8_term["payload_json"]) if _e8_term else {}
    ok.append(("[42/item8] a stopped run's terminal event never records "
               "state 'running' - it agrees with the runs row",
               _e8_tp.get("state") != "running"))
    ok.append(("[42/item8] the terminal event carries the run outcome "
               "that actually ended the run",
               _e8_tp.get("run_outcome") == "escalated"
               and _e8_tp.get("state") in ("stopped", "halted",
                                           "escalated")))
    # [42/item8] END TO END: a call that RAISES must leave a first-class
    # ledger row. The live run's authority counted 6 calls / 87,592
    # tokens while the ledger held only the 4 that returned a result, so
    # every ledger-derived surface under-reported the run by a third and
    # the two calls that explained it were invisible.
    #
    # This also pins the trap that nearly shipped: the writer used a new
    # event_type, the events CHECK constraint rejected it, and the
    # best-effort guard swallowed the error - leaving the ledger exactly
    # as incomplete while every test passed.
    class _RaiseOnSecond(MockTransport):
        def chat(self, role, system, user):
            if len(self.calls) >= 1:
                e = RuntimeError("session-process-died: session main "
                                 "model error [subtype=error_during_"
                                 "execution stop_reason=max_tokens]")
                e.meta = {"kind": "session_process_died",
                          "subtype": "error_during_execution",
                          "session": "main", "reservation_usd": None,
                          "remaining_usd": None}
                raise e
            return super().chat(role, system, user)

    e9_proj = Path(tempfile.mkdtemp()) / "proj9"
    (e9_proj / "src").mkdir(parents=True)
    (e9_proj / "src" / "calc.py").write_text("def add(a, b):\n    return a + b\n")
    e9_tx = _RaiseOnSecond([
        json.dumps({"thought": "simple repo", "action": "done",
                    "patterns": E1_PATTERNS}),
        json.dumps(E1_SPEC)])
    e9_cfg = {"gates": {"comprehension": {"threshold": 1.0}},
              "_workbench": str(e1_wb), "_project_path": str(e9_proj)}
    try:
        e9 = run_ticket(e9_tx, e9_cfg, "E2E-9", "add subtraction to calc",
                        e1_db, project="e2eproj9")
        e9_rid = e9.get("run_id")
    except Exception:
        # run_ticket propagates the transport failure; the run row was
        # already opened, so the run_id is recoverable from the ledger.
        e9_rid = None
    if e9_rid is None:
        with ledger.connect(e1_db) as con:
            _r9 = con.execute("SELECT run_id FROM runs WHERE ticket_id=? "
                              "ORDER BY started_at DESC LIMIT 1",
                              ("E2E-9",)).fetchone()
        e9_rid = _r9["run_id"] if _r9 else None
    _e9_failed = []
    if e9_rid:
        with ledger.connect(e1_db) as con:
            for r in con.execute(
                    "SELECT payload_json, tokens_in, actor, target, "
                    "model, prompt_version FROM "
                    "events WHERE run_id=? AND payload_json LIKE "
                    "'%model call FAILED%'", (e9_rid,)):
                _e9_failed.append((json.loads(r["payload_json"]),
                                   r["tokens_in"], r["actor"], r["target"],
                                   r["model"], r["prompt_version"]))
    ok.append(("[42/item8] a raising model call lands a REAL ledger row - "
               "the write is not silently swallowed",
               len(_e9_failed) >= 1))
    _e9p = _e9_failed[0][0] if _e9_failed else {}
    ok.append(("[42/item8] the persisted failed call carries the typed "
               "failure, the session, the prompt size and the charge",
               _e9p.get("failed") is True
               and (_e9p.get("failure") or {}).get("kind")
               == "session_process_died"
               and isinstance(_e9p.get("prompt_chars"), int)
               and _e9_failed[0][1] == _e9p.get("recorded")))
    ok.append(("[42/item8] the ledger's recorded spend for the failed "
               "call equals the authority's - the surfaces reconcile",
               bool(_e9_failed) and _e9_failed[0][1] > 0))
    # [42/item8b] The row must not be ANONYMOUS: with model and
    # prompt_version NULL, the Models, Prompts and Cost tabs (which
    # group by those columns) dropped the failed call entirely, so the
    # very surfaces a post-mortem reads disagreed with the authority's
    # call count. The requested-role model resolution is truthful and
    # known (it is what the run printed at startup); the agent stamp is
    # the same one a successful call would have carried. cost_usd stays
    # honestly NULL - no price frame ever arrived.
    ok.append(("[42/item8b] the failed row carries the resolved model, "
               "so the Models tab counts the call",
               bool(_e9_failed) and _e9_failed[0][4] == "mock-sonnet"))
    ok.append(("[42/item8b] the failed row carries the agent's prompt "
               "stamp, so the Prompts tab counts the call",
               bool(_e9_failed)
               and str(_e9_failed[0][5] or "").startswith("spec@")))
    # [44/M1] The stamp comes from the CONTENT sent, never the stage
