            ok.append(("CACHE: the cold run PAID for cartography",
                       _c6_actors("E2E-C6A").get("cartographer", {})
                       .get("calls", 0) >= 1))
            ok.append(("CACHE: the worktree run makes ZERO cartographer "
                       "model calls",
                       _c6_actors("E2E-C6B").get("cartographer", {})
                       .get("calls", 0) == 0))
            ok.append(("CACHE: the cold run was a MISS, and said why",
                       any("cache MISS" in l for l in _c6a_tx.progress_log)))
            # Isolation means uncommitted work is NOT part of the executed
