    # live run DATACMP-0-7744ae27 exercised: it was spawned with
    # '--project-path ../dat', that path did not exist, and Docket ran
    # data_project for 25 minutes and 501k tokens instead of refusing.
    def _refuses(cfg_, proj_="resolveproj"):
        try:
            resolve_project_path(dict(cfg_), proj_, fwb)
        except ExplicitProjectPathRefused as e:
            return str(e)
        return None

